import{_ as a,c as i,o as t,a4 as s}from"./chunks/framework.BCDg3NR7.js";const h=JSON.parse('{"title":"GitLab 的仓库迁移","description":"","frontmatter":{},"headers":[],"relativePath":"articles/07-others/代码规范/GitLab 的仓库迁移.md","filePath":"articles/07-others/代码规范/GitLab 的仓库迁移.md","lastUpdated":1747041533000}'),e={name:"articles/07-others/代码规范/GitLab 的仓库迁移.md"},l=s(`<h1 id="gitlab-的仓库迁移" tabindex="-1">GitLab 的仓库迁移 <a class="header-anchor" href="#gitlab-的仓库迁移" aria-label="Permalink to &quot;GitLab 的仓库迁移&quot;">​</a></h1><p>GitLab 仓库迁移可以分为几个步骤，具体取决于你是从一个 GitLab 实例迁移到另一个实例，还是从本地仓库迁移到 GitLab，或者从其他版本控制系统迁移到 GitLab。以下是一般的 GitLab 仓库迁移步骤。</p><h3 id="一、从-gitlab-到-gitlab-的仓库迁移" tabindex="-1">一、从 GitLab 到 GitLab 的仓库迁移 <a class="header-anchor" href="#一、从-gitlab-到-gitlab-的仓库迁移" aria-label="Permalink to &quot;一、从 GitLab 到 GitLab 的仓库迁移&quot;">​</a></h3><h4 id="_1-使用-gitlab-的导入-导出功能迁移项目" tabindex="-1">1. 使用 GitLab 的导入/导出功能迁移项目 <a class="header-anchor" href="#_1-使用-gitlab-的导入-导出功能迁移项目" aria-label="Permalink to &quot;1. 使用 GitLab 的导入/导出功能迁移项目&quot;">​</a></h4><p>GitLab 提供了一个导入和导出的功能来迁移项目。步骤如下：</p><ol><li><strong>导出项目</strong>： <ul><li>登录到 GitLab 实例，打开你要迁移的项目。</li><li>点击右上角的 <strong>Settings</strong>（设置） &gt; <strong>General</strong>（常规设置）。</li><li>滚动到页面底部，找到 <strong>Advanced</strong>（高级）设置，然后点击 <strong>Export project</strong>（导出项目）。</li><li>GitLab 会创建一个 <code>.tar.gz</code> 文件，包含项目的所有内容（代码、问题、合并请求等），下载该文件。</li></ul></li><li><strong>导入项目</strong>： <ul><li>在新的 GitLab 实例中，登录并创建一个新的空项目。</li><li>进入项目页面，点击 <strong>Import project</strong>（导入项目）。</li><li>选择 <strong>GitLab export</strong>，上传你之前下载的 <code>.tar.gz</code> 文件。</li><li>GitLab 会导入项目内容，包括 Git 仓库和项目的其他相关数据。</li></ul></li></ol><h4 id="_2-手动迁移-如果不需要导入的其他信息-如-issues-等" tabindex="-1">2. 手动迁移（如果不需要导入的其他信息，如 issues 等） <a class="header-anchor" href="#_2-手动迁移-如果不需要导入的其他信息-如-issues-等" aria-label="Permalink to &quot;2. 手动迁移（如果不需要导入的其他信息，如 issues 等）&quot;">​</a></h4><p>如果你只需要迁移 Git 仓库（代码），而不关心 issues、合并请求等信息，你可以手动操作：</p><ol><li><p><strong>从旧 GitLab 拉取代码</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git clone --mirror https://old_gitlab_instance/username/repository.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>推送到新 GitLab 实例</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>cd repository.git</span></span>
<span class="line"><span>git remote set-url origin https://new_gitlab_instance/username/repository.git</span></span>
<span class="line"><span>git push --mirror</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li></ol><h3 id="二、从其他-git-服务迁移到-gitlab" tabindex="-1">二、从其他 Git 服务迁移到 GitLab <a class="header-anchor" href="#二、从其他-git-服务迁移到-gitlab" aria-label="Permalink to &quot;二、从其他 Git 服务迁移到 GitLab&quot;">​</a></h3><p>如果你要将仓库从其他 Git 服务（如 GitHub、Bitbucket）迁移到 GitLab，步骤如下：</p><h4 id="_1-从-github-或-bitbucket-克隆仓库" tabindex="-1">1. 从 GitHub 或 Bitbucket 克隆仓库 <a class="header-anchor" href="#_1-从-github-或-bitbucket-克隆仓库" aria-label="Permalink to &quot;1. 从 GitHub 或 Bitbucket 克隆仓库&quot;">​</a></h4><p>假设你要迁移的仓库在 GitHub 或 Bitbucket 上：</p><ol><li><p><strong>克隆 GitHub 仓库</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git clone --mirror https://github.com/username/repository.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>将仓库推送到 GitLab</strong>：</p><ul><li><p>创建一个新的空 GitLab 仓库。</p></li><li><p>在本地仓库中更改远程地址，指向新的 GitLab 仓库：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>cd repository.git</span></span>
<span class="line"><span>git remote set-url origin https://gitlab.com/username/repository.git</span></span>
<span class="line"><span>git push --mirror</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li></ul></li></ol><h4 id="_2-使用-github-bitbucket-的导入功能-对于-github" tabindex="-1">2. 使用 GitHub / Bitbucket 的导入功能（对于 GitHub） <a class="header-anchor" href="#_2-使用-github-bitbucket-的导入功能-对于-github" aria-label="Permalink to &quot;2. 使用 GitHub / Bitbucket 的导入功能（对于 GitHub）&quot;">​</a></h4><p>如果是从 GitHub 迁移到 GitLab，GitLab 提供了从 GitHub 导入的选项：</p><ol><li>在 GitLab 创建一个新项目。</li><li>在项目页面选择 <strong>Import project</strong>（导入项目）。</li><li>选择 <strong>GitHub</strong>，然后按照提示登录 GitHub 帐号，并选择要导入的项目。</li></ol><h3 id="三、迁移-gitlab-用户和权限" tabindex="-1">三、迁移 GitLab 用户和权限 <a class="header-anchor" href="#三、迁移-gitlab-用户和权限" aria-label="Permalink to &quot;三、迁移 GitLab 用户和权限&quot;">​</a></h3><p>如果你不仅需要迁移仓库，还需要迁移 GitLab 用户和权限（例如迁移到新 GitLab 实例时保留用户权限），你可以使用 GitLab 的 <strong>备份和恢复</strong> 功能来迁移所有数据：</p><ol><li><p><strong>备份 GitLab 实例</strong>：</p><ul><li><p>在旧的 GitLab 实例中，运行以下命令来创建备份：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>sudo gitlab-rake gitlab:backup:create</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>这会生成一个包含所有数据的备份文件（包括仓库、用户、权限等）。</p></li></ul></li><li><p><strong>恢复到新 GitLab 实例</strong>：</p><ul><li><p>将备份文件转移到新服务器。</p></li><li><p>在新服务器上运行以下命令来恢复数据：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>sudo gitlab-rake gitlab:backup:restore BACKUP=timestamp_of_backup</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>记得在恢复之前需要停止 GitLab 服务，以避免数据损坏。</p></li></ul></li></ol><h3 id="四、注意事项" tabindex="-1">四、注意事项 <a class="header-anchor" href="#四、注意事项" aria-label="Permalink to &quot;四、注意事项&quot;">​</a></h3><ul><li>在迁移仓库时，要确保你拥有目标仓库的访问权限，否则无法进行推送操作。</li><li>如果你是从其他 Git 服务迁移，可能会丢失某些 GitLab 特有的数据（例如 issues、合并请求等）。因此，使用导入/导出功能迁移时，会保留更多项目的完整性。</li><li>在迁移大仓库时，<code>--mirror</code> 是非常有用的，它会将所有的引用、标签、提交等完整迁移。</li></ul><p>希望这些步骤能帮助你顺利迁移 GitLab 仓库！如果有其他问题，随时告诉我！</p>`,23),n=[l];function r(p,o,b,c,u,d){return t(),i("div",null,n)}const m=a(e,[["render",r]]);export{h as __pageData,m as default};
